from mkgen import *
T=[]; A=lambda *x,**k: a(T,*x,**k)
A(r"\(AOB\) — развёрнутый угол. Луч \(OD\) делит его пропорционально числам 3 и 7. На сколько градусов \(\angle AOD\) меньше, чем \(\angle DOB\)?",r"\(AOB\) — жазыңқы бұрыш. \(OD\) сәулесі оны 3 және 7 сандарына пропорционал бөледі. \(\angle AOD\) бұрышы \(\angle DOB\)-дан неше градусқа кіші?",["36°","72°","54°","126°"],"B","180° : 10 = 18°; углы 54° и 126°; разность 72°.")
A(r"Найдите сумму корней уравнения \(2-|2x+3|=-5\).",r"\(2-|2x+3|=-5\) теңдеуінің түбірлерінің қосындысын табыңыз.",["1","нет корней","−3",r"\(-3\tfrac13\)"],"C","|2x + 3| = 7: x = 2 или x = −5; сумма −3.",ok=["1","түбір жоқ","−3",r"\(-3\tfrac13\)"])
A("Белка за первую неделю зимы сгрызла все орешки. В первый день — некоторое количество, а каждый следующий день на 3 орешка больше, чем в предыдущий. Найдите весь запас, если за третий день она сгрызла 18 орешков.","Тиін қыстың бірінші аптасында барлық жаңғақты кеміріп бітірді. Бірінші күні белгілі бір мөлшерін, ал әр келесі күні алдыңғыға қарағанда 3 жаңғақ артық кеміреді. Үшінші күні 18 жаңғақ кемірсе, бүкіл қорды табыңыз.",["98","126","147","64"],"C","a + 6 = 18, a = 12 (первый день). За 7 дней: 12, 15, …, 30: среднее 21, сумма 7·21 = 147.")
A("Две трубы вместе наполняют бассейн за 2,4 часа. Если одна первая труба наполняет его за 4 часа, то за какое время половину бассейна наполняет одна вторая труба?","Екі құбыр бірге бассейнді 2,4 сағатта толтырады. Егер бір бірінші құбыр оны 4 сағатта толтырса, жартысын жалғыз екінші құбыр қанша уақытта толтырады?",["6 часов","3,6 часа","2 часа","3 часа"],"D","1/2,4 − 1/4 = 5/12 − 3/12 = 1/6: вторая — 6 часов; половина — 3 часа.",ok=["6 сағат","3,6 сағат","2 сағат","3 сағат"])
A("В 7А классе 24 ученика, средний возраст всего класса 12,5 года. Если к ним прибавить возраст куратора, то средний возраст станет ровно 13 лет. Сколько лет куратору?","7А сыныбында 24 оқушы, бүкіл сыныптың орташа жасы 12,5. Оларға куратордың жасын қоссақ, орташа жас дәл 13 болады. Куратор неше жаста?",["18 лет","21 год","25 лет","23 года"],"C","24·12,5 = 300; 25·13 = 325; 325 − 300 = 25.",ok=["18 жас","21 жас","25 жас","23 жас"])
A("Сколько целых чисел в промежутке от 12,8 до 41,9 делятся на 4 без остатка?","12,8 мен 41,9 аралығындағы бүтін сандардың қаншасы 4-ке қалдықсыз бөлінеді?",["6","7","8","10"],"B","16, 20, 24, 28, 32, 36, 40 — 7 чисел.")
A(r"Найдите отношение 3,2 м² к 0,004 га.",r"3,2 м²-тің 0,004 га-ға қатынасын табыңыз.",[r"\(\tfrac45\)",r"\(\tfrac18\)",r"\(\tfrac2{25}\)",r"\(\tfrac5{16}\)"],"C","0,004 га = 40 м²; 3,2 : 40 = 2/25.")
A("Масштаб карты 1 : 2 000 000. Длина отрезка, показывающего весь путь велосипедиста, 5,4 см. Сколько часов он будет в пути при постоянной скорости 18 км/ч?","Картаның масштабы 1 : 2 000 000. Велосипедшінің бүкіл жолын көрсететін кесіндінің ұзындығы 5,4 см. Тұрақты жылдамдығы 18 км/сағ болса, ол жолда қанша сағат болады?",["4 часа","6,5 часа","1,8 часа","6 часов"],"D","5,4·2 000 000 = 10 800 000 см = 108 км; 108 : 18 = 6 ч.",ok=["4 сағат","6,5 сағат","1,8 сағат","6 сағат"])
A("Треугольник KLM со сторонами 6,5 см, 8,5 см и 9 см. Найдите сторону квадрата ABCD, если его периметр равен периметру треугольника KLM.","Қабырғалары 6,5 см, 8,5 см және 9 см KLM үшбұрышы берілген. Периметрі KLM үшбұрышының периметріне тең ABCD шаршысының қабырғасын табыңыз.",["4,5 см","5 см","20 см","6 см"],"D","P = 24 см; сторона 24 : 4 = 6 см.")
A(r"Вычислите: \(-\dfrac{\dfrac{19\cdot12-19\cdot9}3-5{,}6}{6{,}7}-1{,}5\).",r"Есептеңіз: \(-\dfrac{\dfrac{19\cdot12-19\cdot9}3-5{,}6}{6{,}7}-1{,}5\).",["0,5","2,5","2","−3,5"],"D","19·3/3 = 19; 19 − 5,6 = 13,4; 13,4 : 6,7 = 2; −2 − 1,5 = −3,5.")
A(r"Вычислите: \(\big|\,8-|3-(-7{,}2)|+3{,}8\,\big|-0{,}5\).",r"Есептеңіз: \(\big|\,8-|3-(-7{,}2)|+3{,}8\,\big|-0{,}5\).",["0,1","1,1","2,7","−0,6"],"B","|3 + 7,2| = 10,2; 8 − 10,2 + 3,8 = 1,6; |1,6| − 0,5 = 1,1.")
A("Укажите пару взаимно простых чисел.","Өзара жай сандар жұбын көрсетіңіз.",["14 и 21","18 и 27","9 и 16","4 и 10"],"C","НОД(9, 16) = 1; у остальных пар есть общие делители 7, 9, 2.",ok=["14 және 21","18 және 27","9 және 16","4 және 10"])
A("В школе девятиклассники составляют 15% всех учащихся. 20% всех девятиклассников — отличники. Если число отличников в 9-м классе равно 18, сколько всего детей в школе?","Мектепте тоғызыншы сынып оқушылары барлық оқушылардың 15%-ын құрайды. Барлық тоғызыншы сыныптың 20%-ы — үздік оқушылар. 9-сыныптағы үздіктер саны 18 болса, мектепте барлығы қанша бала оқиды?",["500","624","570","600"],"D","18 : 0,2 = 90 девятиклассников; 90 : 0,15 = 600.")
A("На координатной прямой отмечены три точки. Найдите координату точки C, симметричной точке A(−3,6) относительно точки B(−0,8).","Координаталық түзуде үш нүкте белгіленген. B(−0,8) нүктесіне қатысты A(−3,6) нүктесіне симметриялы C нүктесінің координатасын табыңыз.",["2","−2","3","4,4"],"A","C = 2B − A = −1,6 + 3,6 = 2.")
A("Мотоциклист и велосипедист выехали из двух разных городов в одном направлении с постоянной скоростью. Скорость мотоциклиста 112,5 км/ч, велосипедиста 31,25 км/ч. Через какое время мотоциклист догонит велосипедиста, если расстояние между городами 195 км?","Мотоциклші мен велосипедші екі түрлі қаладан бір бағытта тұрақты жылдамдықпен шықты. Мотоциклшінің жылдамдығы 112,5 км/сағ, велосипедшінікі 31,25 км/сағ. Қалалар арасы 195 км болса, мотоциклші велосипедшіні қанша уақыттан кейін қуып жетеді?",["2,5 часа","2,4 часа","3,2 часа","4,4 часа"],"B","Скорость сближения 81,25 км/ч; 195 : 81,25 = 2,4 ч.",ok=["2,5 сағат","2,4 сағат","3,2 сағат","4,4 сағат"])
A("Радиус колеса равен 30 см. Какое расстояние проедет машина, когда колесо сделает 15 оборотов? (π ≈ 3)","Дөңгелектің радиусы 30 см. Дөңгелек 15 айналым жасағанда көлік қандай қашықтық жүреді? (π ≈ 3)",["18 м","27 м","360 м","20 м"],"B","3·2·30·15 = 2700 см = 27 м.")
A(r"Решите уравнение \(5(x-4)=3\) и найдите значение \(2x\).",r"\(5(x-4)=3\) теңдеуін шешіп, \(2x\) мәнін табыңыз.",["2","9,2","4","−4"],"B","x − 4 = 0,6, x = 4,6; 2x = 9,2.")
A("Стороны квадрата уменьшили на 50%. Сколько процентов составляет изначальная площадь от новой площади?","Шаршының қабырғаларын 50%-ға кеміткен. Бастапқы аудан жаңа ауданның неше пайызын құрайды?",["200%","400%","250%","25%"],"B","Новая площадь (1/2)² = 1/4 прежней; прежняя составляет 400% новой.")
A("Турист за 3 дня проехал на велосипеде 110 км. В первый день он проехал в 3 раза меньше, чем во второй, а в третий день на 10 км больше, чем в первый. Сколько километров проехал турист во второй день?","Турист 3 күнде велосипедпен 110 км жүрді. Бірінші күні екінші күнге қарағанда 3 есе аз, ал үшінші күні бірінші күнге қарағанда 10 км артық жүрді. Турист екінші күні неше километр жүрді?",["28 км","60 км","51 км","30 км"],"B","x + 3x + (x + 10) = 110, x = 20; второй день 60 км.")
A(r"Если \(3x-4y=2x\), то найдите, чему равно \(\dfrac xy\).",r"\(3x-4y=2x\) болса, \(\dfrac xy\) неге тең екенін табыңыз.",["2,5",r"\(\tfrac14\)","0,5","4"],"D","x = 4y, значит x/y = 4.")
A(r"Выполните действия: \(4{,}4:11-\left(\tfrac14-\tfrac25\right)\).",r"Амалдарды орындаңыз: \(4{,}4:11-\left(\tfrac14-\tfrac25\right)\).",["−2","3,5","0,55",r"\(\tfrac{15}{200}\)"],"C","4,4 : 11 = 0,4; 1/4 − 2/5 = −0,15; 0,4 + 0,15 = 0,55.")
A(r"Какое из данных чисел в модуле примет самое маленькое значение: \(-3{,}8;\ \dfrac{9{,}6}3;\ \dfrac{17}6;\ -3{,}25\)?",r"Берілген сандардың қайсысының модулі ең кіші мән қабылдайды: \(-3{,}8;\ \dfrac{9{,}6}3;\ \dfrac{17}6;\ -3{,}25\)?",["−3,8",r"\(\tfrac{9{,}6}3\)",r"\(\tfrac{17}6\)","−3,25"],"C","Модули: 3,8; 3,2; 2,83; 3,25. Наименьший у 17/6.")
A(r"Решите уравнение: \(\dfrac{3(2x-1)}2-\dfrac{4x+2}5=4+\dfrac{6x-3}3\).",r"Теңдеуді шешіңіз: \(\dfrac{3(2x-1)}2-\dfrac{4x+2}5=4+\dfrac{6x-3}3\).",["2","19,5","24,5","−6"],"C","Слева 2,2x − 1,9; справа 2x + 3. 0,2x = 4,9; x = 24,5.")
A("В первый магазин привезли A кг фруктов в коробках, во второй — B кг. В каждой коробке по T кг. Какое выражение показывает, на сколько коробок больше привезли во второй магазин, чем в первый?","Бірінші дүкенге жәшіктерде A кг жеміс, екіншісіне B кг әкелді. Әр жәшікте T кг. Екінші дүкенге бірінші дүкенге қарағанда неше жәшік артық әкелгенін қай өрнек көрсетеді?",["A·T − B·T","(A + B) − T","A : T − B : T","B : T − A : T"],"D","Число коробок: B : T и A : T. Разность — B : T − A : T.")
A("Найдите число, 35% которого равно 2,8.","35%-ы 2,8-ге тең санды табыңыз.",["4","8","9,8","80"],"B","2,8 : 0,35 = 8.")
A("Передние колёса трактора имеют длину окружности 2 м, задние 3 м. Какое расстояние проехал трактор, если переднее колесо сделало на 20 оборотов больше заднего?","Трактордың алдыңғы дөңгелегінің шеңбер ұзындығы 2 м, артқысыныкі 3 м. Алдыңғы дөңгелек артқыдан 20 айналым артық жасаса, трактор қандай қашықтық жүрді?",["60 м","120 м","100 м","240 м"],"B","d/2 − d/3 = d/6 = 20, d = 120 м.")
A("Поезд длиной 300 м проехал мимо фонарного столба за 20 с. За сколько времени он проедет туннель длиной 450 м?","Ұзындығы 300 м пойыз шам бағанының жанынан 20 с өтті. Ұзындығы 450 м туннельден ол қанша уақытта өтеді?",["1 мин","40 с","50 с","1 мин 20 с"],"C","Скорость 15 м/с. (300 + 450) : 15 = 50 с.",ok=["1 мин","40 с","50 с","1 мин 20 с"])
A("Отношение цены книги к стоимости 6 ручек равно отношению чисел 8 и 5, а отношение цены книги к цене пенала 3 : 2. Стоимость этих вещей вместе 2750 тг. Найдите цену одной ручки.","Кітап бағасының 6 қаламның құнына қатынасы 8 және 5 сандарының қатынасындай, ал кітап бағасының пенал бағасына қатынасы 3 : 2. Бұл заттардың жалпы құны 2750 тг. Бір қаламның бағасын табыңыз.",["125 тг","250 тг","100 тг","30 тг"],"A","Книга 24m, 6 ручек 15m, пенал 16m: 55m = 2750, m = 50. 6 ручек — 750 тг, одна — 125 тг.")
A(r"Найдите значение выражения \(\dfrac5{2c}-\dfrac4c\), если \(c=-2{,}5\).",r"\(c=-2{,}5\) болса, \(\dfrac5{2c}-\dfrac4c\) өрнегінің мәнін табыңыз.",["2","−1","0,6","1"],"C","5/(−5) = −1; 4/(−2,5) = −1,6; −1 + 1,6 = 0,6.")
A("Площадь посевного поля 3 га. Если на каждые 60 м² земли требуется 2,4 кг зерна, сколько зерна нужно на посев всего поля?","Егіс алаңының ауданы 3 га. Әр 60 м² жерге 2,4 кг дән керек болса, бүкіл алаңға қанша дән керек?",["1,7 т","224 кг","1200 кг","680 кг"],"C","30 000 : 60 = 500; 500·2,4 = 1200 кг.")
A(r"Найдите количество корней уравнения \(|2x-6{,}5|=8-6\).",r"\(|2x-6{,}5|=8-6\) теңдеуінің түбірлер санын табыңыз.",["0","1","2","4"],"C","|2x − 6,5| = 2 — два корня.")
A(r"Вычислите: \(8-\dfrac{2}{3-\dfrac{5}{4-1\frac12}}\).",r"Есептеңіз: \(8-\dfrac{2}{3-\dfrac{5}{4-1\frac12}}\).",["2","3,5","6","5"],"C","4 − 1,5 = 2,5; 5 : 2,5 = 2; 3 − 2 = 1; 2 : 1 = 2; 8 − 2 = 6.")
A(r"Найдите координату точки \(N\), если \(K(-3)\), \(L(5)\), \(|KL|=2|LM|\) и \(1{,}5|LM|=|MN|\) (точки идут в порядке \(K,L,M,N\)).",r"\(K(-3)\), \(L(5)\), \(|KL|=2|LM|\) және \(1{,}5|LM|=|MN|\) болса, \(N\) нүктесінің координатасын табыңыз (нүктелер \(K,L,M,N\) ретімен).",["1","13","15","11"],"C","KL = 8, LM = 4, M(9), MN = 6, N(15).")
A("Найдите периметр фигуры, составленной в один ряд из 6 одинаковых квадратов, если площадь каждого равна 36 см².","Ауданы 36 см² болатын 6 бірдей шаршыдан бір қатарға құралған фигураның периметрін табыңыз.",["84 см","72 см","96 см","60 см"],"A","Сторона 6 см; прямоугольник 36 × 6: P = 2(36 + 6) = 84 см.")
A(r"Решите неравенство: \(-4\le\dfrac{2x-6}3<2\).",r"Теңсіздікті шешіңіз: \(-4\le\dfrac{2x-6}3<2\).",[r"\(x\in[-3;6)\)",r"\(x\in(-3;6]\)",r"\(x\in[-1;3{,}2)\)",r"\(x\in(2;3)\)"],"A","−12 ≤ 2x − 6 < 6 → −6 ≤ 2x < 12 → −3 ≤ x < 6.")
A("В морской воде содержится 6% соли. Сколько граммов воды нужно выпарить из 600 г морской воды, чтобы соль составляла 15% общей массы?","Теңіз суында 6% тұз бар. 600 г теңіз суынан тұз жалпы массаның 15%-ын құрауы үшін қанша грамм суды буландыру керек?",["360 г","240 г","300 г","60 г"],"A","Соли 36 г; при 15% масса раствора 240 г; выпарить 600 − 240 = 360 г.")
A("Найдите наименьшее натуральное число, которое при делении на 5 в остатке даёт 4, а при делении на 8 в остатке даёт 7.","5-ке бөлгенде қалдығы 4, ал 8-ге бөлгенде қалдығы 7 болатын ең кіші натурал санды табыңыз.",["39","79","31","19"],"A","n + 1 делится на 5 и на 8, то есть на 40; n = 39.")
A("Стоимость 3 тетрадей и 2 ручек равна 1400 тг. Тетрадь стоит 300 тг. Сколько стоит одна ручка?","3 дәптер мен 2 қаламның құны 1400 тг. Дәптер 300 тг тұрады. Бір қалам қанша тұрады?",["200 тг","250 тг","300 тг","500 тг"],"B","3·300 = 900; 1400 − 900 = 500; 500 : 2 = 250.")
A("Среднее арифметическое пяти чисел равно 12. Сумма четырёх из них 46. Найдите пятое число.","Бес санның орта арифметикалық мәні 12. Олардың төртеуінің қосындысы 46. Бесінші санды табыңыз.",["14","12","10","16"],"A","5·12 = 60; 60 − 46 = 14.")
A("Отношение числа мальчиков к числу девочек в классе 3 : 5, а всего в классе 32 ученика. Сколько в классе девочек?","Сыныптағы ұлдар санының қыздар санына қатынасы 3 : 5, ал сыныпта барлығы 32 оқушы. Сыныпта қанша қыз бар?",["12","16","20","24"],"C","32 : 8 = 4 на часть; девочек 5·4 = 20.")
write(T,"T05_MATH","t05-math.ts","Тест 5 · Математика")
